def run_template_eval(strategy_a, trials=1000, seed=42):
    random.seed(seed)
    monster_a = {
        "id": "m_emberton",
        "name": "Emberton",
        "element": "pyro",
        "moves": ['ember', 'pyroclasm', 'bulwark', 'mend']
