                        for w_mend in [0.2, 0.5, 0.8]:
                            strat = {
                                "opening_move": opening,
                                "move_weights": {
                                    "ember": w_ember,
                                    "pyroclasm": w_pyro,
                                    "bulwark": w_bulwark,
                                    "mend": w_mend
                                },
                                "switch_to_defense_below": switch_def,
                                "defense_move": "mend", # mend to outlast
                                "aggression": aggression,
                                "prefer_super_effective": True
                            }
                            wins = run_template_eval(strat, 100, seed=123)
                            if wins > best_wins:
                                best_wins = wins
                                best_strat = strat
                                print(f"New Best: {wins}/100 | Open: {opening} | Def: {switch_def} | Agg: {aggression} | W: E:{w_ember} P:{w_pyro} B:{w_bulwark} M:{w_mend}")

print("\nBest against template opponent:")
print(best_strat)
